import{_ as s,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"The Matrix: Infinite-Horizon World Generation with Real-Time Moving Control","description":"","frontmatter":{"title":"The Matrix: Infinite-Horizon World Generation with Real-Time Moving Control","arxiv":"2412.03568","date":"2024-12-04","authors":"Ruili Feng, Han Zhang, Zhantao Yang, Jie Xiao, Zhilei Shu, Zhiheng Liu, Andy Zheng, Yukun Huang, Yu Liu, Hongyang Zhang","categories":"cs.AI","topics":"世界模型, 无限长视频生成, 实时交互控制","outline":[2,2]},"headers":[],"relativePath":"papers/2412.03568.md","filePath":"papers/2412.03568.md","lastUpdated":null}'),p={name:"papers/2412.03568.md"};function r(l,a,i,o,m,h){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="the-matrix-infinite-horizon-world-generation-with-real-time-moving-control" tabindex="-1">The Matrix: Infinite-Horizon World Generation with Real-Time Moving Control <a class="header-anchor" href="#the-matrix-infinite-horizon-world-generation-with-real-time-moving-control" aria-label="Permalink to &quot;The Matrix: Infinite-Horizon World Generation with Real-Time Moving Control&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2412.03568" target="_blank" rel="noreferrer">2412.03568</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-12-04</td></tr><tr><td><strong>作者</strong></td><td>Ruili Feng, Han Zhang, Zhantao Yang, Jie Xiao, Zhilei Shu, Zhiheng Liu, Andy Zheng, Yukun Huang, Yu Liu, Hongyang Zhang</td></tr><tr><td><strong>分类</strong></td><td>cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把预训练视频 DiT 的批量去噪改造成滑动窗口内的流式去噪队列（Swin-DPM），配上因果交叉注意力的键盘控制模块与一致性模型蒸馏，得到 720p、8–16 FPS、可无限延长的可控世界模拟器。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文要造的是&quot;神经交互式模拟器&quot;：用户按键盘，模型实时吐出下一段 720p 画面，可以一直走下去不结束，而且能从沙漠开进草原、开进水里、开进办公室。这里有三个互相冲突的目标——<strong>画质</strong>、<strong>无限长度</strong>、<strong>实时帧级控制</strong>——此前的工作每次只能拿到其中一到两项。</p><p>价值在于两处。一是 3A 游戏开发成本动辄数千万美元，且资产复用率低，数据驱动的世界模型能把&quot;搭世界&quot;变成&quot;训模型&quot;。二是数据可得性：真实世界里连续可控的运动数据极难采集（谁去开着车在办公室里绕圈），而游戏里可以随便采。论文的核心论点之一就是<strong>用少量有标注的 3A 游戏数据 + 大量无标注真实视频，能把控制能力零样本迁移到真实域</strong>——例子是让 BMW X3 开进办公室，这个场景在游戏数据与真实数据里都不存在。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文把相关工作分成两支。一支是为智能体学习服务的世界模型：Recurrent World Models、Dreamer v1/v2/v3、TD-MPC、DayDreamer、SafeDreamer、MuDreamer、MuZero。它们的目标是重建观测与奖励以便策略优化，样本效率增益可达 1000% 以上，但从不追求高保真渲染。</p><p>另一支是世界模拟，按控制粒度再分两类。<strong>视频级控制</strong>（起始给一次信号，模型生成整段）：UniSim、Pandora、GameGen-X、MicroVGG、GAIA-1。这类方法要做连续控制只能把独立生成的片段拼起来，接缝可见。<strong>帧级控制</strong>（每隔几帧调整一次）：Genie、DIAMOND、GameNGen、Oasis。</p><p>不够用的地方被 Table 1 摊开得很清楚。训练语料方面，此前全是 2D 游戏、Atari、Mario、DOOM、Minecraft、CS:GO，画面复杂度与真实世界差距过大；分辨率上，DOOM 类只有 240p，能到 720p 的要么不支持帧级控制要么不能泛化；速度上，Genie 慢到 1 FPS。更关键的是<strong>控制泛化</strong>一栏——除了本文只有一个&quot;Yes&quot;，意味着此前的模型只会在它训练过的那个游戏里响应按键。</p><p>作者对&quot;为什么此前没人同时做到&quot;给出了具体解释：帧级动作标注成本极高（谁来逐帧标&quot;这一帧按了 W&quot;），所以大家只能退到视频级；而 Sora 一类的强生成模型受限于约一分钟的序列长度，长度靠拼接。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>三条已有线索。第一，预训练视频 DiT 已经具备极强的场景先验和画质，从零训小模型是在浪费这份先验——但前人为了控制精度和速度，恰恰都在从零训小模型。第二，注意力的显存与算力随时长平方增长，这是长度限制的直接原因；而视频的时间依赖其实是局部的，超出一定窗口的注意力计算基本无用。第三，一致性模型已经把扩散采样压到个位数步。</p><p>顺着这三条走：既然要用预训练 DiT，就必须解决它&quot;只能一次生成几秒&quot;的问题；既然时间依赖是局部的，就可以只在一个滑动窗口内做注意力；既然窗口在滑动，就没必要等整段视频一起去噪完——可以让窗口里的 token 各自处在不同噪声水平，最左边那个去噪完就出队解码，右边补一个纯噪声进来。这就是流式去噪。</p><p>至于动作标注的成本问题，作者绕开了人工标注：游戏的角色坐标就躺在 CPU 内存里，用 Cheat Engine 直接读出来，与 OBS 录制的画面对齐，就得到了免费的逐帧动作-画面对。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>扩散模型默认&quot;一整段视频一起从纯噪声走到干净&quot;，这个批处理假设同时封死了长度和延迟。The Matrix 把它改成流水线：窗口里排着一队 token，越靠左噪声越低，每走 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步去噪，最左边那个就毕业出队去解码，右边补进一个纯噪声。于是视频变成了可以一直往外吐的流，而不是一次做完的块。控制则通过因果交叉注意力注入——每个按键只影响当前及其后 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span></span></span></span> 个 token，保证&quot;按下去马上有反应&quot;而不是&quot;影响整段&quot;。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以&quot;在 Forza Horizon 5 的沙漠里按住前进、再按左转&quot;为例：</p><ul><li><strong>数据采集（GameData 平台）</strong>。由三部分构成：控制、模拟、观测。Forza Horizon 5 用自动脚本随机游走（动作简化为前进 D、前进+左转 DL、前进+右转 DR），并用游戏自带的 telemetry 读取 XYZ 坐标、速度、加速度；若 40 秒内的 40 个位置点能被半径 80 米的圆覆盖，就判定卡住并随机传送。Cyberpunk 2077 地形复杂，改为人工远程操控（动作为 W/U/D/L/R），用 Cheat Engine 读坐标。Reshade 插件关掉 UI 与 HUD 的着色器渲染并统一画风，OBS 以 2560×1600 原生分辨率录制；实测控制信号与画面的延迟稳定在 3 帧以内，可直接从时间轴上减掉。NPC 与来往车辆被 mod 关闭。</li><li><strong>数据清洗</strong>。用 FFmpeg 切成 6 秒片段，用 InternVL 基于 12 个均匀关键帧生成描述并人工纠错（正文另一处说使用 GPT-4o 标注，两处表述不一致）。五道过滤：控制信号配平（反复删除占比最高的信号直至均衡）、加速度突变检测碰撞、位移过短检测卡住、加速度与速度夹角过大检测&quot;控制与运动不匹配&quot;、相邻帧像素差过大检测伪影。最终 Source 数据集为 750k 有标注 + 120 万无标注、全部 60 FPS；附录另给出 Forza 约 120 万对、Cyberpunk 约 100 万对的采集量（推测是过滤前的原始规模）。</li><li><strong>骨干</strong>。2.3B 参数的公开视频 DiT，3D VAE 把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 帧编码为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 个 token，32 个 attention block，每块含自注意力、交叉注意力与 GELU FFN，patch embedding 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 的 3D 卷积，特征维 2048。</li><li><strong>Interactive Module</strong>。先把键盘输入翻译成自然语言：Forza 里按 W 是 &quot;The car is driving forward&quot;，Cyberpunk 里 W 加上抬头是 &quot;The man is moving forward and looking up&quot;；无标注数据统一用 &quot;The camera is moving in an unknown way&quot;，训练时以概率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1</span></span></span></span> 把有标注的替换成这句默认描述以增强鲁棒。文本过 T5 编码，再经两层线性加 SiLU 得到向量，与当前 token 及其后 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> 个 token 拼接，通过<strong>因果交叉注意力</strong>注入；每两个 DiT block 后插一次，共 16 个模块，新增 0.4B 参数，总计 2.7B。</li><li><strong>Swin-DPM</strong>。窗口内维护长度为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 的 token 队列，各 token 噪声水平不同，步长 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>。每 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步去噪后（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 为求解器总步数），最左端噪声最低的 token 出队进入 cache 并解码；右端补入一个高斯噪声 token。出队的 token 以噪声水平 0 重新挂回队列参与注意力，直到下一个 token 出队为止——这是保证跨窗口连续性的关键。训练时采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 个 token（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span>），前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 个只做 warmup 不回传梯度，损失只算在后 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 个上；推理同理，前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 个丢弃。</li><li><strong>Stream Consistency Model</strong>。把 Swin-DPM 检查点作为 teacher，用一阶段引导蒸馏（把 CFG 并入 student）蒸成四步一致性模型，ODE 求解器用 Euler、单步步长 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">25/1000</span></span></span></span>，训练 10,000 步。加速 10–20 倍，达到 8–16 FPS。</li><li><strong>四阶段训练</strong>。无标注 Source 上 LoRA（rank 128）warmup 20,000 步 → 冻结 DiT 训 Interactive Module 20,000 步 → Swin-DPM 全参数微调 60,000 步 → 一致性蒸馏 10,000 步。全程 batch 32、学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>、bfloat16；输入统一 1280×720、16 FPS；超过 25,200 帧的序列用 DeepSpeed Ulysses 序列并行分到 8 卡。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。（正文未给出目标函数或收敛性论证；唯一的形式化内容是流式去噪的离散参数化：窗口长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span>、出队步长 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>、每 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步出队一个 token 且 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 等于扩散求解器总步数、因果影响范围 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span>、无标注描述替换概率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1</span></span></span></span>。）</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>评测指标分两组：视觉质量用 FID、FVD、CLIP Score，在 2,048 秒随机生成视频上算；控制精度用 Move-PSNR 与 Move-LPIPS，即按固定测试集的键盘输入与文本提示生成 2,048 秒视频，与带真实运动的实拍/实录视频比较。</p><p><strong>问题一：Interactive Module 有用吗？</strong> 在三个场景上测：Forza 开车、Cyberpunk 城市行走、DROID 机械臂（取 5 万段 6 秒片段，带 7 个关节角的逐帧动作标注）。Table 2 显示 Forza 上加入 Interactive Module 后 Move-PSNR 从 26.89 升到 28.98、Move-LPIPS 从 0.128 降到 0.125，同时 FID 从 141.11 降到 119.20。DROID 一组的存在说明这套控制机制不限于游戏，作者明确说是为具身场景设计的验证。</p><p><strong>问题二：Swin-DPM 换来的长度，代价是什么？</strong> 加上 Swin-DPM 后 Forza 的 Move-PSNR 继续升到 29.90、Move-LPIPS 降到 0.113，但 FVD 从 1211.30 涨到 1651.50、CLIP 从 0.27 掉到 0.24。作者承认&quot;牺牲了部分视觉质量&quot;，但认为仍高于此前的世界模拟器。生成结果包括 1 分钟长视频（沙漠、河流、草地、雪地、昼夜转换）与 2.5 分钟跨场景视频（中途切换 DiT 文本提示换环境），补充材料里还有半小时样例。</p><p><strong>问题三：实时化的代价？</strong> 加上 SCM 后速度从 0.8 FPS 提到 8–16 FPS，Move-LPIPS 进一步降到 0.109、Move-PSNR 微降到 29.73，FVD 涨到 1936.79、FID 153.80。结论是控制精度基本无损、速度提升一个量级、视觉分布指标继续退化。</p><p><strong>问题四：能泛化到分布外世界吗？</strong> 三类证据：在提示里描述室内场景就能让车在办公室里开；把提示里的中心物体换成&quot;人&quot;，人就会响应按键移动；关掉 Interactive Module 后模型退化为一个可生成长视频的普通文本到视频模型。</p><p>整个实验部分<strong>没有与 Genie、GameNGen、Oasis 等前人方法做同指标的定量对比</strong>，Table 1 是特性对比表而非性能表。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话</strong>：The Matrix 把预训练视频 DiT 的批式去噪改造成滑动窗口内的流式去噪队列（Swin-DPM），使一个只能生成几秒的模型可以无限往外吐帧；键盘输入被翻译成自然语言、经 T5 编码后通过因果交叉注意力注入，每个按键只影响当前及后续 4 个 token，实现帧级响应；训练数据来自 GameData 平台，用 Cheat Engine 直接从 CPU 内存读取游戏状态与 OBS 录制画面对齐，把逐帧动作标注的成本压到接近零；一致性模型蒸馏把速度从 0.8 FPS 提到 8–16 FPS，控制精度几乎无损；少量有标注游戏数据加大量无标注真实视频，让控制能力零样本迁移到训练中不存在的场景（如车开进办公室）。</p><p><strong>三句话</strong>：长视频生成的瓶颈不在模型容量，而在&quot;一整段一起去噪&quot;这个批处理假设；把它改成流水线队列，长度限制就消失了。控制信号以自然语言为中介注入，使得无标注数据可以用一句默认描述参与训练，从而把泛化能力从游戏带到真实场景。代价是视觉分布指标（FVD/FID）随着 Swin-DPM 与蒸馏逐级退化，论文选择用画质换长度与速度。</p><p><strong>一句话</strong>：把扩散从&quot;批处理&quot;改成&quot;流水线&quot;，世界模型才能既长又快。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是：<strong>时间依赖被限制在长度为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 的窗口内是无损的</strong>。整个 Swin-DPM 建立在这条假设上；如果不成立，模型生成的就不是&quot;一个持续存在的世界&quot;，而是&quot;一串局部自洽、全局失忆的画面&quot;。</p><p>它在实践中很可能不成立，因为世界模型的核心诉求恰恰是长程一致性：转过身回来，刚才那栋楼还在不在、还是不是同一栋。窗口外的 token 不参与注意力计算，模型没有任何机制记住 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 之外的场景内容。论文提供的证据是间接的——一分钟与 2.5 分钟的定性样例、以及&quot;能生成半小时视频&quot;的声明。但这些片段全是<strong>持续向前移动</strong>的场景（开车穿越地形、城市行走），恰好是最不需要长程记忆的运动模式：往前开的时候，场景本来就该不断更新。论文没有做闭环测试（绕一圈回到起点看是否一致），也没有报告任何长程一致性指标。而 Table 2 里 FVD 随 Swin-DPM 上升这一现象，可以推断至少部分来自窗口截断造成的分布漂移。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不复现整套系统，只检验窗口假设：</p><ul><li>数据：任取一个可脚本化的驾驶或步行环境（Forza 若不可得，用 CARLA 或 Unreal 示例城市），录制 200 条&quot;绕行闭环&quot;轨迹——从某点出发，绕一圈回到出发点与朝向。</li><li>实现：取任一开源视频扩散模型，实现最简版 Swin-DPM（固定窗口、出队即解码、cache 回挂），在直行数据上训练。</li><li>测量：在闭环轨迹上做 rollout，把最后一帧与真实起点帧计算 LPIPS 与 CLIP 相似度；同时用同一模型在<strong>非闭环</strong>直行轨迹上计算同段长度的画质指标作对照。窗口长度取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 两组。</li><li>判据：若闭环末帧与起点帧的 LPIPS 随轨迹长度显著上升，且加大窗口能明显缓解，就说明窗口截断是长程一致性的直接瓶颈；若加大窗口无改善，则问题出在模型缺少显式记忆而非窗口大小，两种结论指向完全不同的修法。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击是提出一个<strong>替代解释</strong>：论文声称的&quot;零样本域泛化&quot;（车开进办公室、人响应按键）可能主要来自预训练 DiT 的文本到视频先验，而非 Source 数据集教会的控制迁移。检验方式很直接：拿未经任何 Source 微调的原始 2.3B DiT，用同样的文本提示（&quot;a BMW X3 driving through an office&quot;）生成视频，再对比 The Matrix 的输出。如果两者的场景合成能力相当，那么 Source 数据贡献的只是&quot;按键→运动&quot;的映射，而<strong>跨域</strong>这部分是骨干白送的——论文把它列为核心贡献之一，这个归因就需要修正。论文的 Table 2 里没有这一组对照。</p><p>第二条攻击针对可预测的失败条件。Forza 的动作空间只有三个信号（D/DL/DR），全部包含&quot;前进&quot;；Cyberpunk 只有 W/U/D/L/R。也就是说，训练分布里<strong>从来没有倒车、没有刹车、没有静止</strong>。构造这样的测试：给模型下达&quot;后退&quot;或&quot;停下&quot;的指令，观察它是否仍然向前移动。若如此，说明 Interactive Module 学到的是&quot;按键→前进速度的方向微调&quot;，而非完整的运动学控制。这类失败在真实交互中是致命的，且完全可以从数据构造中预测出来。</p><p>第三点较小但值得记：论文正文说用 GPT-4o 生成描述，附录 B.2.2 说用 InternVL 生成并人工纠错，两处不一致，标注管线的实际形态存疑。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：Swin-DPM 用有限窗口换来了无限长度，但也因此永久失去了长程一致性——这不是把窗口调大能解决的，因为注意力的代价是平方级的，而世界的持续时间是无界的。同时，出队即解码的设计意味着模型<strong>没有可写入的外部状态</strong>，它的全部&quot;记忆&quot;就是窗口里那几个 token。</p><p><strong>新的 framing</strong>：把世界模型从&quot;自回归视频流&quot;改成&quot;生成式的持久场景状态 + 可微渲染&quot;。也就是说，模型维护一个显式但压缩的场景表示（一组带位置的隐向量，类似 3D Gaussian 或 slot 的形式），每帧的生成条件是&quot;当前视角 + 从场景表示中检索出的相关部分&quot;，而窗口注意力只负责短程动力学。相邻领域可借的工具有两个：检索增强生成里的稀疏记忆检索，以及 SLAM 里的回环检测与位姿图优化——后者恰好就是&quot;绕一圈回来要对得上&quot;这个问题的经典解法。</p><p><strong>第一个实验</strong>：在一个中等规模的游戏场景里录制大量闭环轨迹，训练一个轻量的&quot;场景记忆&quot;模块：它接收 Swin-DPM 出队的 token 与对应位姿，写入一个键为位姿、值为压缩特征的记忆库；生成时按当前位姿做近邻检索，把检索结果作为额外的交叉注意力条件。评测就用 §10 的闭环 LPIPS：如果带记忆的版本在 20 米、50 米、100 米闭环上的末帧-起点帧相似度显著高于纯 Swin-DPM，而 FPS 下降小于 20%，就说明&quot;短程用注意力、长程用检索&quot;这个分工是可行的——这会把无限长世界模拟从&quot;看起来连续&quot;推进到&quot;确实是同一个世界&quot;。</p>',47)])])}const u=s(p,[["render",r]]);export{g as __pageData,u as default};
